<?php
require __DIR__.'/../config/database.php';require_admin();$rows=$pdo->query('SELECT l.*,u.full_name FROM admin_logs l JOIN users u ON u.id=l.admin_id ORDER BY l.id DESC LIMIT 300')->fetchAll();$pageTitle='Nhật ký hoạt động';require __DIR__.'/../includes/header.php';require __DIR__.'/_nav.php';
